// Parse manual report request
const input = $input.first().json;

const reportType = input['Report Type'] || 'Weekly';
let startDate, endDate;

const now = new Date();

switch (reportType) {
  case 'Weekly':
    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    endDate = now;
    break;
  case 'Monthly':
    startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    endDate = new Date(now.getFullYear(), now.getMonth(), 0);
    break;
  case 'Quarterly':
    const quarter = Math.floor(now.getMonth() / 3);
    startDate = new Date(now.getFullYear(), (quarter - 1) * 3, 1);
    endDate = new Date(now.getFullYear(), quarter * 3, 0);
    break;
  case 'Custom Date Range':
    startDate = new Date(input['Start Date (for custom range)'] || now.getTime() - 30 * 24 * 60 * 60 * 1000);
    endDate = new Date(input['End Date (for custom range)'] || now);
    break;
}

const sections = input['Include Sections'] || 'Executive Summary,KPI Dashboard';
const deliveryMethod = input['Delivery Method'] || 'Email';

return {
  json: {
    reportType,
    startDate: startDate.toISOString().split('T')[0],
    endDate: endDate.toISOString().split('T')[0],
    sections: typeof sections === 'string' ? sections.split(',').map(s => s.trim()) : sections,
    deliveryMethod: typeof deliveryMethod === 'string' ? deliveryMethod.split(',').map(s => s.trim()) : deliveryMethod,
    emailRecipients: input['Email Recipients'] || '',
    slackChannel: input['Slack Channel'] || '#sales-reports'
  }
};

// Fetch sales data from CRM and other sources
const config = $input.first().json;

// In production, this would fetch from CRM API
// Example data structure
const salesData = {
  reportConfig: config,
  generatedAt: new Date().toISOString(),

  // Deals closed in period
  closedWon: [
    // { id, name, company, amount, closeDate, owner, daysToClose }
  ],
  closedLost: [
    // { id, name, company, amount, closeDate, owner, lossReason, competitor }
  ],

  // Active pipeline
  pipeline: [
    // { id, name, company, amount, stage, probability, expectedCloseDate, owner, daysInStage }
  ],

  // Activities in period
  activities: {
    emails: 0,
    calls: 0,
    meetings: 0,
    demos: 0
  },

  // New leads in period
  newLeads: 0,
  convertedLeads: 0,

  // Quota data by rep
  quotas: [
    // { rep, quota, achieved, percentage }
  ],

  // Previous period for comparison
  previousPeriod: {
    closedWonValue: 0,
    closedWonCount: 0,
    newLeads: 0
  }
};

return { json: salesData };

// Calculate key performance indicators
const data = $input.first().json;

const formatCurrency = (amount) => {
  return '$' + (amount || 0).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
};

const formatPercent = (value) => {
  return (value || 0).toFixed(1) + '%';
};

// Revenue metrics
const closedWonValue = data.closedWon.reduce((sum, d) => sum + d.amount, 0);
const closedWonCount = data.closedWon.length;
const closedLostValue = data.closedLost.reduce((sum, d) => sum + d.amount, 0);
const closedLostCount = data.closedLost.length;

// Win rate
const totalClosed = closedWonCount + closedLostCount;
const winRate = totalClosed > 0 ? (closedWonCount / totalClosed) * 100 : 0;

// Average deal size
const avgDealSize = closedWonCount > 0 ? closedWonValue / closedWonCount : 0;

// Average days to close
const avgDaysToClose = closedWonCount > 0 
  ? data.closedWon.reduce((sum, d) => sum + (d.daysToClose || 30), 0) / closedWonCount 
  : 0;

// Pipeline metrics
const pipelineValue = data.pipeline.reduce((sum, d) => sum + d.amount, 0);
const weightedPipeline = data.pipeline.reduce((sum, d) => sum + (d.amount * d.probability / 100), 0);
const pipelineCount = data.pipeline.length;

// Pipeline coverage (weighted pipeline / quota remaining)
const totalQuota = data.quotas.reduce((sum, q) => sum + q.quota, 0);
const totalAchieved = data.quotas.reduce((sum, q) => sum + q.achieved, 0);
const quotaRemaining = totalQuota - totalAchieved;
const pipelineCoverage = quotaRemaining > 0 ? (weightedPipeline / quotaRemaining) * 100 : 100;

// Lead metrics
const leadConversionRate = data.newLeads > 0 ? (data.convertedLeads / data.newLeads) * 100 : 0;

// Period over period comparison
const revenueGrowth = data.previousPeriod.closedWonValue > 0 
  ? ((closedWonValue - data.previousPeriod.closedWonValue) / data.previousPeriod.closedWonValue) * 100 
  : 0;

const kpis = {
  ...data,

  kpis: {
    // Revenue
    revenue: {
      value: closedWonValue,
      formatted: formatCurrency(closedWonValue),
      deals: closedWonCount,
      growth: formatPercent(revenueGrowth),
      growthValue: revenueGrowth
    },

    // Win Rate
    winRate: {
      value: winRate,
      formatted: formatPercent(winRate),
      won: closedWonCount,
      lost: closedLostCount,
      lostValue: formatCurrency(closedLostValue)
    },

    // Average Deal Size
    avgDealSize: {
      value: avgDealSize,
      formatted: formatCurrency(avgDealSize)
    },

    // Sales Cycle
    salesCycle: {
      value: avgDaysToClose,
      formatted: Math.round(avgDaysToClose) + ' days'
    },

    // Pipeline
    pipeline: {
      value: pipelineValue,
      formatted: formatCurrency(pipelineValue),
      weighted: formatCurrency(weightedPipeline),
      weightedValue: weightedPipeline,
      count: pipelineCount,
      coverage: formatPercent(pipelineCoverage),
      coverageValue: pipelineCoverage
    },

    // Quota
    quota: {
      target: formatCurrency(totalQuota),
      achieved: formatCurrency(totalAchieved),
      percentage: formatPercent((totalAchieved / totalQuota) * 100),
      percentageValue: (totalAchieved / totalQuota) * 100
    },

    // Leads
    leads: {
      new: data.newLeads,
      converted: data.convertedLeads,
      conversionRate: formatPercent(leadConversionRate)
    },

    // Activities
    activities: data.activities
  }
};

return { json: kpis };

// Generate rep performance data
const data = $input.first().json;

// Group closed deals by owner
const repDeals = {};
data.closedWon.forEach(deal => {
  if (!repDeals[deal.owner]) {
    repDeals[deal.owner] = { won: [], lost: [] };
  }
  repDeals[deal.owner].won.push(deal);
});

data.closedLost.forEach(deal => {
  if (!repDeals[deal.owner]) {
    repDeals[deal.owner] = { won: [], lost: [] };
  }
  repDeals[deal.owner].lost.push(deal);
});

// Calculate rep metrics
const formatCurrency = (amount) => '$' + (amount || 0).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

const repPerformance = data.quotas.map(quota => {
  const deals = repDeals[quota.rep] || { won: [], lost: [] };
  const wonValue = deals.won.reduce((sum, d) => sum + d.amount, 0);
  const wonCount = deals.won.length;
  const lostCount = deals.lost.length;
  const totalDeals = wonCount + lostCount;
  const winRate = totalDeals > 0 ? (wonCount / totalDeals) * 100 : 0;
  const avgDealSize = wonCount > 0 ? wonValue / wonCount : 0;

  // Pipeline for this rep
  const repPipeline = data.pipeline.filter(d => d.owner === quota.rep);
  const pipelineValue = repPipeline.reduce((sum, d) => sum + d.amount, 0);
  const pipelineCount = repPipeline.length;

  return {
    rep: quota.rep,
    quota: quota.quota,
    quotaFormatted: formatCurrency(quota.quota),
    achieved: wonValue,
    achievedFormatted: formatCurrency(wonValue),
    quotaAttainment: ((wonValue / quota.quota) * 100).toFixed(1) + '%',
    quotaAttainmentValue: (wonValue / quota.quota) * 100,
    dealsWon: wonCount,
    dealsLost: lostCount,
    winRate: winRate.toFixed(1) + '%',
    avgDealSize: formatCurrency(avgDealSize),
    pipelineValue: formatCurrency(pipelineValue),
    pipelineCount: pipelineCount,
    status: (wonValue / quota.quota) >= 1 ? 'On Track' : (wonValue / quota.quota) >= 0.7 ? 'At Risk' : 'Behind'
  };
});

// Sort by quota attainment
repPerformance.sort((a, b) => b.quotaAttainmentValue - a.quotaAttainmentValue);

return {
  json: {
    ...data,
    repPerformance
  }
};

// Generate pipeline analysis
const data = $input.first().json;

const formatCurrency = (amount) => '$' + (amount || 0).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

// Pipeline by stage
const stages = ['Qualification', 'Discovery', 'Proposal', 'Negotiation'];
const byStage = stages.map(stage => {
  const stageDeals = data.pipeline.filter(d => d.stage === stage);
  const value = stageDeals.reduce((sum, d) => sum + d.amount, 0);
  const weighted = stageDeals.reduce((sum, d) => sum + (d.amount * d.probability / 100), 0);

  return {
    stage,
    count: stageDeals.length,
    value: formatCurrency(value),
    valueRaw: value,
    weighted: formatCurrency(weighted),
    weightedRaw: weighted,
    avgDaysInStage: stageDeals.length > 0 
      ? Math.round(stageDeals.reduce((sum, d) => sum + (d.daysInStage || 0), 0) / stageDeals.length)
      : 0
  };
});

// Deals at risk (low probability or stale)
const atRisk = data.pipeline.filter(d => d.probability < 40 || d.daysInStage > 14);
const atRiskValue = atRisk.reduce((sum, d) => sum + d.amount, 0);

// Deals closing this month
const now = new Date();
const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
const closingThisMonth = data.pipeline.filter(d => {
  const closeDate = new Date(d.expectedCloseDate);
  return closeDate <= endOfMonth;
});
const closingThisMonthValue = closingThisMonth.reduce((sum, d) => sum + d.amount, 0);

// Loss analysis
const lossReasons = {};
data.closedLost.forEach(deal => {
  const reason = deal.lossReason || 'Not Specified';
  if (!lossReasons[reason]) {
    lossReasons[reason] = { count: 0, value: 0 };
  }
  lossReasons[reason].count++;
  lossReasons[reason].value += deal.amount;
});

const topLossReasons = Object.entries(lossReasons)
  .map(([reason, data]) => ({ reason, count: data.count, value: formatCurrency(data.value) }))
  .sort((a, b) => b.count - a.count)
  .slice(0, 5);

// Competitor analysis
const competitors = {};
data.closedLost.forEach(deal => {
  if (deal.competitor) {
    if (!competitors[deal.competitor]) {
      competitors[deal.competitor] = { count: 0, value: 0 };
    }
    competitors[deal.competitor].count++;
    competitors[deal.competitor].value += deal.amount;
  }
});

const topCompetitors = Object.entries(competitors)
  .map(([name, data]) => ({ competitor: name, losses: data.count, value: formatCurrency(data.value) }))
  .sort((a, b) => b.losses - a.losses)
  .slice(0, 5);

return {
  json: {
    ...data,
    pipelineAnalysis: {
      byStage,
      atRisk: {
        count: atRisk.length,
        value: formatCurrency(atRiskValue),
        deals: atRisk.slice(0, 10) // Top 10
      },
      closingThisMonth: {
        count: closingThisMonth.length,
        value: formatCurrency(closingThisMonthValue)
      },
      topLossReasons,
      topCompetitors
    }
  }
};

